<template>
 <div ref="anchor" class="move-option" :style="typeStyle(info?.type || resolvedType)" @mouseenter="hoverStart" @mouseleave="hover=false">
  <button v-bind="$attrs" class="move-action" :class="buttonClass" :disabled="disabled" @click="choose"><slot/><small v-if="reason" class="move-block-reason">{{ reason }}</small><small v-if="warning" class="move-area-warning">{{ warning }}</small></button>
  <info-button v-if="move" class="move-info-button" :aria-label="'Informations sur '+(info?.label||move)" :aria-expanded="opened" @pointerdown.stop @click.stop="open" @keydown.stop data-move-info/>
  <aside v-if="hover && !opened && info" class="move-hover-info" :style="position" role="tooltip"><strong>{{ info.label }}</strong><p>{{ metadata }}</p><p>{{ info.description }}</p><p v-if="reason">{{ reason }}</p><p v-if="warning">{{ warning }}</p></aside>
  <div v-if="opened" v-back="close" data-move-inspection class="move-info-backdrop" @pointerdown.stop @click.stop @keydown.stop="keys" @keyup.stop>
   <section ref="sheet" role="dialog" aria-modal="true" aria-label="Informations sur la capacité" class="move-info-sheet"><header><div><small>CONSULTER LA CAPACITÉ</small><h3>{{ info?.label || move }}</h3></div><button ref="close" aria-label="Fermer les informations" @click="close">×</button></header><p>{{ metadata }}</p><p>{{ info?.description || 'Description indisponible.' }}</p><p v-if="reason" class="move-block-reason">{{ reason }}</p><p v-if="warning" class="move-area-warning">{{ warning }}</p><small>Cette consultation ne lance aucune attaque. Le chronomètre du combat continue.</small><button class="move-info-return" @click="close">Revenir aux capacités</button></section>
  </div>
 </div>
</template>
<script>
import InfoButton from './InfoButton.vue';
import {inspectMove} from '@/services/moveInspection';
import {typeBadgeStyle,localizeTypeName} from '@/services/pokemonTypes';
export default {
 components:{InfoButton},inheritAttrs:false,props:{move:String,resolvedType:String,reason:String,warning:String,disabled:Boolean,buttonClass:String},
 data:()=>({hover:false,opened:false,position:{}}),
 computed:{info(){return inspectMove(this.move,this.resolvedType);},metadata(){const m=this.info;if(!m)return '';return `${localizeTypeName(m.type)} · ${{physical:'Physique',special:'Spéciale',status:'Statut'}[m.category]||'—'} · Puissance ${m.power>0?m.power:m.category==='status'?'—':'Variable'} · Précision ${m.accuracy>0?m.accuracy+' %':'—'} · ${m.pp} PP max`; }},
 watch:{move(){this.hover=false;this.opened=false;}},
 methods:{typeStyle:typeBadgeStyle,choose(){if(this.disabled)return;this.hover=false;this.$emit('choose');},hoverStart(){if(!matchMedia('(hover:hover)').matches)return;const r=this.$refs.anchor.getBoundingClientRect(),w=Math.min(330,innerWidth-24),h=220;this.position={width:w+'px',left:Math.max(12,Math.min(innerWidth-w-12,r.left))+'px',top:Math.max(12,Math.min(innerHeight-h-12,r.top>=h+14?r.top-h-8:r.bottom+8))+'px'};this.hover=true;},open(){this.hover=false;this.previous=document.activeElement;this.opened=true;this.$nextTick(()=>this.$refs.close?.focus({preventScroll:true}));},close(){this.opened=false;this.$nextTick(()=>{if(this.previous?.isConnected)this.previous.focus({preventScroll:true});});},keys(e){if(e.key==='Escape'){e.preventDefault();this.close();}if(e.key==='Tab'){const n=[...this.$refs.sheet.querySelectorAll('button')];e.preventDefault();n[(n.indexOf(document.activeElement)+(e.shiftKey?-1:1)+n.length)%n.length]?.focus();}}}
};
</script>
<style scoped>
.move-option{position:relative;min-width:0;display:flex;align-items:stretch;border-radius:12px}.move-action{flex:1;min-width:0;width:100%;padding-right:43px!important}.move-info-button{position:absolute;right:2px;top:2px;z-index:1}.move-block-reason,.move-area-warning{display:block;font:600 10px/1.4 var(--journal-font);white-space:normal;margin-top:5px}.move-block-reason{color:var(--journal-danger)}.move-area-warning{color:var(--journal-heading)}.move-hover-info{position:fixed;z-index:4100;box-sizing:border-box;max-height:220px;overflow:auto;pointer-events:none;padding:14px;border:1px solid var(--journal-border);border-left:4px solid var(--pokemon-type-color);border-radius:10px;background:var(--journal-paper);color:var(--journal-ink);box-shadow:var(--journal-shadow);font:12px/1.5 var(--journal-font);text-align:left}.move-hover-info strong{font-size:16px}.move-hover-info p{margin:7px 0}.move-info-backdrop{position:fixed;inset:0;z-index:4200;padding:12px;display:grid;place-items:center;background:var(--journal-backdrop)}.move-info-sheet{box-sizing:border-box;width:min(440px,100%);max-height:calc(100dvh - 24px);overflow:auto;background:var(--journal-paper);color:var(--journal-ink);border:1px solid var(--journal-border);box-shadow:0 12px 36px #10203130;border-radius:15px;padding:18px;text-align:left;font:14px/1.55 var(--journal-font)}.move-info-sheet header{display:flex;gap:10px;justify-content:space-between;align-items:center}.move-info-sheet header small{font-size:9px;color:var(--journal-muted)}.move-info-sheet h3{font:600 24px Georgia,serif;margin:4px 0}.move-info-sheet button{min-height:44px;min-width:44px;border:1px solid var(--journal-border);border-radius:8px;background:var(--journal-card);color:var(--journal-ink);cursor:pointer;font:inherit}.move-info-sheet>small{display:block;color:var(--journal-muted);font-size:11px}.move-info-return{width:100%;margin-top:16px}.move-action:disabled{cursor:default}@media(pointer:coarse){.move-info-button{right:0;top:0}.move-action{padding-right:45px!important}}
</style>
